impl Solution {
    pub fn count_subarrays(nums: Vec<i32>) -> i32 {
        let mut count = 0;
        for i in 1..nums.len() - 1 {
            if nums[i - 1] as i64 + nums[i + 1] as i64 == (nums[i] as i64) * 2 {
                count += 1;
            }
        }
        count
    }
}

